commands.command:
/usr/bin/bash -lc "jq -n --argfile f .exp_agent/findings_round_01.json --argfile r .exp_agent/round_completion_01.json '
  def expected: ["'$f[] | {rule, path:.relative_path, line:.line, column:.column}] | sort_by(.rule,.path,.line,.column);
  def reported: [$r.entity_repairs[] as $e | $e.locations[] | {rule:$e.rule,path:$e.relative_path,line:.line,column:.column}] | sort_by(.rule,.path,.line,.column);
  (expected) as $a | (reported) as $b | {expected:($a|length),reported:($b|length),missing:[$a[]|select(. as $x|($b|index($x))|not)],extra:[$b[]|select(. as $x|($a|index($x))|not)]}'"'"

/usr/bin/bash -lc "node - <<'NODE'
const ts = require('/home/zhihao/deveco/command-line-tools/codelinter/linter/arkPerfCheck/node_modules/typescript');
const source = 'class Step { power:number=0; minute:number=0; id:string=\"\" } const a: Step[] = [{power: 1, minute: 2}];';
